50	            throw new FileNotFoundException($"Block '{name}' not found (expected '{path}').");
51	        var manifest = JsonSerializer.Deserialize<BlockManifest>(File.ReadAllText(path), JsonOpts.Default)
52	                       ?? throw new InvalidDataException($"Failed to parse '{path}'.");
