using MonoDreams.Cli.Manifest;

namespace MonoDreams.Cli.Resolver;

internal static class DependencyResolver
{
    public static List<string> Resolve(Registry registry, IEnumerable<string> requested, IEnumerable<string> alreadyInstalled)
    {
        var seen = new HashSet<string>(alreadyInstalled);
        var visiting = new HashSet<string>();
        var ordered = new List<string>();

        foreach (var name in requested) Visit(name, registry, seen, visiting, ordered, path: new Stack<string>());
        return ordered;
    }

    private static void Visit(string name, Registry registry, HashSet<string> seen, HashSet<string> visiting, List<string> ordered, Stack<string> path)
    {
        if (seen.Contains(name)) return;
        if (!visiting.Add(name))
        {
            var cycle = string.Join(" -> ", path.Reverse().Concat(new[] { name }));
            throw new InvalidOperationException($"Cyclic dependency: {cycle}");
        }

        path.Push(name);
        var manifest = registry.GetBlock(name);
        foreach (var dep in manifest.Dependencies)
            Visit(dep, registry, seen, visiting, ordered, path);
        path.Pop();

        visiting.Remove(name);
        seen.Add(name);
        ordered.Add(name);
    }
}

namespace MonoDreams.Demo.Dialogue;

/// Dialogue block demo. A very basic top-down Sprout Lands scene: walk the player around
/// a grass field with WASD, approach the cow NPC at the top-left, and press E to start a
/// Yarn conversation. The line text wraps and reveals character-by-character; pick a reply
/// with the up/down arrows and E. Yarn <c>&lt;&lt;emote who kind&gt;&gt;</c> commands show
/// the speaker's framed portrait inside the box (left = NPC, right = player) and
/// <c>&lt;&lt;react who mark&gt;&gt;</c> pops a reaction mark above a character's head.
///
/// Showcases the dialogue block (<see cref="DialogueSystem"/> + Yarn runtime, fed an
/// in-memory-compiled program so the demo ships no .yarn asset), the rendering-text reveal,
/// and sprite rendering on the Main target.

